const fs = require('fs');
const path = require('path');
const vm = require('vm');

const root = process.argv[2];
const html = fs.readFileSync(path.join(root, 'index.html'), 'utf8');
const scripts = [...html.matchAll(/<script\b[^>]*\bsrc=["']([^"']+)["'][^>]*>/gi)].map(m => m[1]);
const elements = new Map();
function element(id) {
  if (!elements.has(id)) elements.set(id, {
    id, textContent: '', hidden: true, style: {}, attrs: {},
    classList: { values: new Set(), toggle(name, on) { on ? this.values.add(name) : this.values.delete(name); }, contains(name) { return this.values.has(name); } },
    setAttribute(name, value) { this.attrs[name] = String(value); },
    getAttribute(name) { return this.attrs[name]; },
    parentElement: null,
  });
  return elements.get(id);
}
const track = element('tide-track');
const bar = element('tide-bar');
bar.parentElement = track;
const canvas = element('game');
canvas.width = 480; canvas.height = 320;
canvas.getContext = () => ({ clearRect(){}, fillRect(){}, beginPath(){}, arc(){}, fill(){}, fillStyle:'' });
const context = {
  document: { getElementById: element },
  window: { addEventListener(){} },
  performance: { now: () => 0 },
  requestAnimationFrame(){}, clearInterval(){}, Math, console,
};
vm.createContext(context);
for (const src of scripts) vm.runInContext(fs.readFileSync(path.join(root, src), 'utf8'), context, { filename: src });
const snap = () => vm.runInContext(`({remainingSeconds, roundState, shellCount, shells:shells.length, player:[player.x,player.y], recoveries:activeRecoveries.length})`, context);
const initial = snap();
console.log(`scripts=${scripts.join(',')}`);
console.log(`initial remaining=${initial.remainingSeconds} tide=${element('tide').textContent} bar=${bar.style.width} aria=${track.getAttribute('aria-valuenow')} shells=${initial.shells}`);
vm.runInContext('update(50)', context);
let s = snap();
console.log(`at10 remaining=${s.remainingSeconds} urgent=${element('hud').classList.contains('urgent')} status=${element('tide-status').textContent} tide=${element('tide').textContent}`);
vm.runInContext('update(0.001)', context);
console.log(`below10 urgent=${element('hud').classList.contains('urgent')} tide=${element('tide').textContent}`);
vm.runInContext('shellCount=4; shellCountElement.textContent="4"; activeRecoveries.push({}); keys.ArrowRight=true; update(20)', context);
s = snap();
console.log(`settle remaining=${s.remainingSeconds} state=${s.roundState} tide=${element('tide').textContent} bar=${bar.style.width} result=${JSON.stringify(element('result').textContent)} recoveries=${s.recoveries}`);
vm.runInContext('const before=JSON.stringify({player,shellCount,n:shells.length}); update(1); settleRound(); settleRound(); const spawnResult=spawnShell(); globalThis.after={before,after:JSON.stringify({player,shellCount,n:shells.length}),spawnResult,result:resultElement.textContent};', context);
console.log(`idempotent frozen=${context.after.before===context.after.after} spawn=${context.after.spawnResult} result=${JSON.stringify(context.after.result)}`);
if (scripts.join(',') !== 'main.js' || initial.remainingSeconds !== 60 || element('tide').textContent !== '0' || s.roundState !== 'settled' || !context.after.before === context.after.after) process.exitCode = 1;

const fs = require('fs');
const path = require('path');
for (const dir of process.argv.slice(2)) {
  const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');
  const refs = [...html.matchAll(/(?:src|href)=["']([^"']+)["']/gi)]
    .map(match => match[1]).filter(ref => !/^([a-z]+:|#)/i.test(ref));
  for (const ref of refs) {
    const exists = fs.existsSync(path.resolve(dir, ref));
    console.log(`${dir} ref=${ref} exists=${exists}`);
    if (!exists) process.exitCode = 1;
  }
}
